-- V006__create_record_tables.sql — BC: record（SCHEMA §3.5, §8.1 V006）
--   record_type_catalog / records
-- 依賴 V001（schema record + record.type_enum）。Generated by gencode[foundation-migrations].
-- 建表順序依同 BC FK 拓撲：record_type_catalog → records。
-- ════════════════════════════════════════════════════════════════════════════

-- ── record.record_type_catalog（經營史類型 Lookup，SCHEMA §3.5.2）────────────────
CREATE TABLE record.record_type_catalog (
  type_code    record.type_enum  PRIMARY KEY,
  label        TEXT              NOT NULL,
  description  TEXT,
  is_active    BOOLEAN           NOT NULL DEFAULT TRUE
);

COMMENT ON TABLE record.record_type_catalog IS 'record BC 類型 Lookup（CONSTANTS §9）';

-- ── record.records（經營史聚合根，append-only，SCHEMA §3.5.1）────────────────────
CREATE TABLE record.records (
  id          BIGSERIAL         PRIMARY KEY,
  account_id  BIGINT            NOT NULL,              -- Cross-BC: app-layer ID
  type        record.type_enum  NOT NULL REFERENCES record.record_type_catalog (type_code),  -- 同 BC FK（ON DELETE RESTRICT 預設）
  payload     JSONB             NOT NULL,
  created_at  TIMESTAMPTZ       NOT NULL DEFAULT now()
);

CREATE INDEX idx_records_acct ON record.records (account_id, type, created_at DESC);

COMMENT ON TABLE  record.records      IS 'record BC 經營史（append-only；破產/成就/傳承）。來源 schema.sql L61';
COMMENT ON COLUMN record.records.type IS 'bankruptcy/achievement/legacy（CONSTANTS §9；不在集合 → 400）';

